quests[13748] = { id = 13748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Edge Of Winter", description = "That's the last time I ever spar with a death knight.\n\nIn southern Crystalsong Forest, overlooking the Crystal Vice's exit, you will find Lord Everblaze. Kill him and take the everburning ember from his corpse.\n\nBring it to the center of Winter's Breath Lake in northern Howling Fjord, and use it to free the maiden encased in ice. She is the guardian of an ancient sword and will award it to whoever frees her.\n\nProve your worth and earn the weapon that she has guarded for so long, {name}.", sourceObjective = "Ambrose Boltspark at the Argent Tournament Grounds wants you to bring him Winter's Edge.", progress = "Did you win the blade I seek?", completion = "The blade is as fine as the stories say. It would seem there's little reason to complete the repairs on my customary blade. Winter's Edge is far superior and I will continue to carry it. You have my thanks, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13749] = { id = 13749, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valiant's Field Training", description = "The tournament is a time for testing your skills against your peers, but we must not forget that the real enemy, the Scourge, will not wait. As you hone your skills against others, so should you maintain your edge in combat against the enemy.\n\nTravel to the area southwest of the Valley of Fallen Heroes and north of Corp'rethar. There, the Scourge raises dead heroes and turns them against us. Defeat these minions of the Scourge, do honor to our allies, and keep yourself prepared for combat.", sourceObjective = "Tickin Gearspanner at the Argent Tournament Grounds wants you to kill 10 Converted Heroes.", completion = "Welcome back from your exercises, {name}. I'm confident that you will make us proud when the competition starts.", sourceObjectiveStatus = "unverified-source-field" }
quests[13750] = { id = 13750, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grand Melee", description = "The grand melee is the most important of the tournament's competitions. We know everyone's looking forward to seeing us in the competition. To that end, we've been honing our skills against the valiants representing the other Alliance capitals.\n\nI suggest you do the same.\n\nGo to the stables outside the pavilion, equip your lance, mount the stabled turbostrider, and challenge the valiants. They wait in the Alliance Valiants' Ring just outside our tent.", sourceObjective = "Bring 3 Marks of the Valiant to Flickin Gearspanner at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion.", progress = "Have you completed your training for the grand melee?", completion = "Well done. Training against the other valiants is one of the best ways to prepare yourself for tournament competition. I know you'll make us proud, {name}.", sourceObjectiveStatus = "unverified-source-field" }
